from pathlib import Path
import argparse,json,gzip,statistics,math
p=argparse.ArgumentParser();p.add_argument('--repo',required=True);a=p.parse_args();R=Path(a.repo);B=R/'docs/reports/20261014-noise-cem'
ledger=json.loads((R/'docs/noise-cem-shared-ledger.json').read_text());out={};rows=[]
def med(values):return statistics.median(values)if values else None
for r in ledger['completed']:
 task,name=r['task'],r['method'];x=json.loads(gzip.decompress((R/r['report']).read_bytes()));traces=[t for c in x['records']for t in c['trace']if t['plan_completed']]
 ref=json.loads(gzip.decompress((R/'docs/reports/20261014-self-refine/jobs'/f'{task}-leflow/report.json.gz').read_bytes()))
 refs={c['id']:c for c in ref['records']};initial=[];first_cost_equal=[]
 for c in x['records']:
  t=c['trace'][0];old=refs[c['id']]['trace'][0]
  if name in ['noise_cem','noise_random']:
   delta=t['noise_search']['round_best_costs'][0][0]-old['local_cost'];first_cost_equal.append(delta==0)
   assert delta==0, (task,name,c['id'],delta)
  initial.append({'case':c['id'],'reference_cost':old['local_cost'],'new_cost':t['local_cost'],'reference_success':refs[c['id']]['success'],'new_success':c['success']})
 mincost=[t['local_cost']for t in traces];errors=[t['observed_prefix_prediction_mse']for t in traces if 'observed_prefix_prediction_mse'in t]
 improvements=[(t['noise_search']['incumbent_costs'][0][0]-t['local_cost'])/max(t['noise_search']['incumbent_costs'][0][0],1e-12)for t in traces]
 rounds={str(i):sum(t['selected_index']//x['identity']['noise_search']['samples']==i for t in traces)for i in range(x['identity']['noise_search']['rounds'])}
 result={'completed_decisions':len(traces),'observed_prefixes':len(errors),'median_selected_terminal_mse':med(mincost),'median_factual_prefix_prediction_mse':med(errors),'median_fractional_score_reduction_within_search':med(improvements),'selected_round_counts':rounds,'initial_pool_cost_bitwise_equal_to_reference':all(first_cost_equal)if first_cost_equal else None,'first_decisions':initial,'action_limit_failures':sum(c['failure_reason']=='action_limit'for c in x['records']),'timeouts':x['metrics']['timeouts']}
 out[f'{task}-{name}']=result
 rows.append((task,name,x['metrics']['successes'],x['metrics']['mean_decision_ms'],result))
lines=['# Noise-space search: failure and behavior analysis','',f"{len(rows)}/12 full physical evaluations are available; zero optimizer updates. All methods reuse the frozen LeFlow head and original development cases/limits. Full method and paired success tables are in [the result report](NOISE_CEM_SHARED_RESULTS_20261014.md).",'','|Task|Variant|Success /50|ms/decision|Median selected terminal MSE|Median factual prefix prediction MSE|','|---|---|---:|---:|---:|---:|']
for task,name,wins,ms,v in rows:lines.append(f"|{task}|{name}|{wins}|{ms:.2f}|{v['median_selected_terminal_mse']:.5f}|{v['median_factual_prefix_prediction_mse']:.5f}|")
if len(rows)==12:
 lines+=['','The measured outcome is mixed and does not support a reliable CEM improvement over LeFlow or matched random search. Unprojected CEM gives9/50 PushT and41/50 Cube versus12/40 for LeFlow and12/40 for sequential random search. Shell CEM gives10/39 versus15/39 for matched shell-random search. CEM versus its sequential control swaps3 wins/6 losses on PushT and3/2 on Cube; shell CEM swaps3/8 on PushT and2/2 on Cube. The one-case Cube gain is insufficient for a general superiority claim.','','All600 cases have zero controller timeouts; every failure exhausts the50-action allowance. This regression therefore is not explained by deadline truncation. The CEM rounds improve their own predicted cost: the median within-decision reduction is28.6% on PushT and30.3% on Cube, compared with8.8% and13.8% for independent sequential random search. Adaptive proposals are usually selected, but optimizing this surrogate more strongly does not consistently improve completion. No rejected action was physically executed, so this does not isolate world-model error, proposal quality or goal representation as the cause.','','CEM decisions take143ms PushT and157ms Cube, roughly2.8 times the reused reference. A192-candidate batch takes66–67ms PushT and82ms Cube, about1.3–1.4 times reference latency, with the same nominal3072/960 candidate work. That is a measured batching advantage, not proof of identical random pools or better outcomes.','']
lines+=['','The retained LeFlow reference is12/50 PushT at50.43ms/decision and40/50 Cube at57.39ms/decision. All six search variants spend3 times its candidate-level flow/world work per decision; the192-candidate random controls are the correct adaptive-search comparisons. Equal candidate work does not imply equal observed latency. No trained weight, task representation or action rule is changed.','','For unprojected CEM and sequential random sampling, every first-round first-decision best cost is bitwise identical to the retained reference on each completed task. Later rounds retain an evaluated incumbent, and recorded incumbent costs never increase. Subsequent decisions visit different physical states and may use different random pools; they are not counterfactual comparisons. Shell projection and one-batch192 sampling do not promise an identical first pool.','','A non-increasing predicted cost does not guarantee task success. Candidate gradients, TTT or new critics are absent. Lower selected cost across separate methods may reflect different visited states or exploitation of the surrogate; these runs cannot distinguish those causes or reveal the physical outcome of rejected candidates. Prefix-error medians likewise use each method’s own trajectories and numbers of observed prefixes, and are diagnostic rather than independent accuracy experiments. Final prefixes ending the episode are not observed by a next planner decision.','','CPU185 numerical/adapter/regression checks and both real-TRAIN checkpoint gates passed before launch. Real sampler/RNG parity, action-unit bounds, exact3072/960 work counts, shell norms, deadline propagation and frozen-state checks passed. The completed-run audit separately verifies all cases, weights, source and process/log completion. No new sampler/indexing bug has been demonstrated. These checks do not establish that latent terminal MSE ranks physically successful plans.','','All raw reports, candidate-cost distributions, selected round and noise-scale telemetry, actual executed actions, reset audits, paired successes/regressions and factual prefix errors are preserved. All50 trajectory archives per run remain on the server; their full inventory is published after completion, with first10 archives per run in Git. No trajectory figure is delivered or claimed visually inspected. This one-seed reused-development pilot supports a screening comparison, not a SOTA, novelty or held-out-generalization claim.']
(R/'docs/NOISE_CEM_SHARED_FAILURE_ANALYSIS_20261014.md').write_text('\n'.join(lines)+'\n')
(B/'behavior-analysis.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({'physical_runs':len(rows),'all_unprojected_initial_round_costs_equal':all(v['initial_pool_cost_bitwise_equal_to_reference'] is not False for v in out.values()),'score_and_behavior_summaries':{k:{a:b for a,b in v.items()if a!='first_decisions'}for k,v in out.items()}},indent=2))
